-- V111__extend_school_district_normalisation.sql
-- Issue #1830: V79/V80's district normalisation CASE misses two UDISE spellings actually
-- present in the raw school-import dataset (scripts/data/schools/output/karnataka_schools_seed.sql,
-- generated by scripts/prepare_schools_data.py — currently applied by NO script, so this is a
-- latent bug: it does not bite the live seed today (scripts/db/fixtures/bangalore-mangalore-
-- schools-seed.sql uses district='Bengaluru', which already normalises).
--
-- REAL IMPACT (counted directly against the UDISE seed file, not estimated):
--   BENGALURU U SOUTH   181 schools  -- rescued by this migration
--   BENGALURU U NORTH    52 schools  -- rescued by this migration
--   BENGALURU RURAL    1,167 schools -- NOT rescued; deliberately left NULL (see below)
--   --------------------------------
--   total               1,400 schools currently silently dropped from Discover (area_key stays
--                                    NULL forever) the moment anyone loads the UDISE-derived seed.
--
-- This migration closes 233 of those 1,400 rows (17%) — BENGALURU U SOUTH + BENGALURU U NORTH.
-- The remaining 1,167 rows (83%), BENGALURU RURAL, are DELIBERATELY left unnormalised. Do not
-- read this migration as closing the ~1,400-row gap: it only closes the 233-row slice below.
--
-- The missing spellings:
--   'BENGALURU U SOUTH'  -- Bengaluru Urban South: 2016 administrative split of the old
--   'BENGALURU U NORTH'  -- undivided Bengaluru Urban district. Same urban core already
--                         -- handled by the bare 'bengaluru'/'bangalore' spellings below —
--                         -- unambiguously the correct district for existing 'Bengaluru'-district
--                         -- areas (V71/V106 seed EVERY Bangalore area with district='Bengaluru').
--   'BENGALURU RURAL'    -- Bengaluru Rural: a GENUINELY DIFFERENT administrative district
--                         -- (Devanahalli/Doddaballapur/Hoskote/Nelamangala taluks), not the
--                         -- urban core. DELIBERATELY NOT added to the 'bengaluru' bucket below —
--                         -- see [PRODUCT REVIEW NEEDED] note.
--
-- [PRODUCT RULING — DECIDED, do not relitigate] 'BENGALURU RURAL' (1,167 of the 1,400 affected
-- rows) is left UNNORMALISED, by explicit product decision:
--
--     "BENGALURU RURAL is a separate administrative/product geography. Do not normalise it to the
--      Bengaluru Urban bucket. Keep its schools unassigned by the existing urban-area algorithm."
--
-- It falls through to its own 'bengaluru rural' bucket via the ELSE branch (same as today), so its
-- schools remain area_key = NULL and are not attributed by the urban-area algorithm.
--
-- WHY: 'BENGALURU U SOUTH' / 'U NORTH' are the SAME district under a post-2016 name — mapping them
-- to 'bengaluru' is a SPELLING normalisation. Bengaluru Rural is a GENUINELY DIFFERENT
-- administrative district. Folding it into 'bengaluru' would not be normalisation; it would attach
-- genuinely rural schools (Devanahalli, Hoskote, Nelamangala) to URBAN locality badges wherever they
-- fall within the 10 km cap of a fringe centroid (Yelahanka, Bagalur, Mallasandra) — precisely the
-- mis-attribution class that #1737 / #1828 / #1829 spent three PRs eliminating.
--
-- Bengaluru Rural ONBOARDING / COVERAGE POLICY is tracked separately in issue #1836. That is a
-- product decision about whether and how to serve that geography — NOT a normalisation bug, and
-- NOT in scope here. Any such change must ship as a NEW forward Flyway migration.
--
-- SCOPE: extend V80's trigger function (assign_school_area_key, CREATE OR REPLACE — same
-- function, not a new one) with the corrected CASE, then backfill ONLY rows where
-- area_key IS NULL (V79's pattern — never re-derive existing non-null rows; wholesale
-- re-derivation against the full area catalogue was measured to collapse curated Bengaluru
-- school counts from 32 to 6, see V109's header). Does NOT touch V79, V80, V109, V110, or
-- school_discover_area_coverage; those files are immutable/out of scope for this migration.
--
-- SINGLE SOURCE OF TRUTH: the district-normalisation CASE previously existed as 3 independent
-- literal copies (trigger function, backfill UPDATE, guard). To eliminate the risk of the
-- copies drifting apart (exactly the defect class #1830 exists to fix), it is now a single
-- IMMUTABLE SQL function, normalise_school_district(TEXT), called from every site below.

-- ── 0. Single source of truth for district normalisation ──────────────────────────────────
-- IMMUTABLE: pure function of its input, safe to use in index expressions / query predicates.

CREATE OR REPLACE FUNCTION public.normalise_school_district(p_district TEXT)
RETURNS TEXT
LANGUAGE sql
IMMUTABLE
AS $$
    SELECT CASE
        WHEN LOWER(TRIM(p_district)) IN (
            'bengaluru urban', 'bangalore urban', 'bangalore',
            'bengaluru u south', 'bengaluru u north'
        ) THEN 'bengaluru'
        WHEN LOWER(TRIM(p_district)) IN ('dakshina kannada', 'mangaluru') THEN 'mangalore'
        ELSE LOWER(TRIM(p_district))
    END;
$$;

-- ── 1. Extend the V80 trigger function's district-normalisation CASE ──────────────────────
-- CREATE OR REPLACE of the SAME function V80 created (public.assign_school_area_key) —
-- this is not a new function, and the trigger created by V80 (trg_school_area_key) picks up
-- the new function body automatically; no DROP/CREATE TRIGGER needed.

CREATE OR REPLACE FUNCTION assign_school_area_key()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
DECLARE
    v_norm_district TEXT;
    v_computed_area_key TEXT;
BEGIN
    -- Only proceed if district and coordinates are provided
    IF NEW.district IS NULL OR NEW.latitude IS NULL OR NEW.longitude IS NULL THEN
        RETURN NEW;
    END IF;

    -- Normalise district (V111: extended with UDISE 'BENGALURU U SOUTH'/'BENGALURU U NORTH'
    -- spellings; 'BENGALURU RURAL' deliberately left un-normalised — see header note above).
    v_norm_district := public.normalise_school_district(NEW.district);

    -- Find nearest configured area within same normalised district, within 10km
    -- Uses NEW.latitude/longitude directly (geog is GENERATED ALWAYS, not yet set in BEFORE trigger)
    SELECT a.area_key
    INTO v_computed_area_key
    FROM areas a
    WHERE public.normalise_school_district(a.district) = v_norm_district
    AND a.geo_center_lon IS NOT NULL
    AND a.geo_center_lat IS NOT NULL
    AND ST_DWithin(
        ST_Point(NEW.longitude, NEW.latitude)::geography,
        ST_Point(a.geo_center_lon, a.geo_center_lat)::geography,
        10000  -- 10 km hard cap; matches V79 MAX_ASSIGNMENT_METERS
    )
    ORDER BY
        ST_Distance(
            ST_Point(NEW.longitude, NEW.latitude)::geography,
            ST_Point(a.geo_center_lon, a.geo_center_lat)::geography
        ) ASC,
        a.area_key ASC  -- deterministic tiebreak
    LIMIT 1;

    -- IS DISTINCT FROM guard (unchanged from V80): only write area_key if the computed value
    -- actually differs from what is already set.
    IF v_computed_area_key IS DISTINCT FROM NEW.area_key THEN
        NEW.area_key := v_computed_area_key;
    END IF;

    RETURN NEW;
END;
$$;

-- ── 2. Backfill: assign area_key to previously-unmatched rows using the corrected CASE ────
-- WHERE area_key IS NULL only (V79's pattern) — safely re-runnable, never re-attributes an
-- existing non-null area_key (operator overrides, V109 corrections, and correctly-matched
-- rows are all preserved untouched).

UPDATE schools s
SET area_key = (
    SELECT a.area_key
    FROM areas a
    WHERE public.normalise_school_district(s.district) = public.normalise_school_district(a.district)
    AND ST_DWithin(
        s.geog,
        ST_Point(a.geo_center_lon, a.geo_center_lat)::geography,
        10000  -- 10 km hard cap; uses idx_schools_geog_gist for pruning
    )
    ORDER BY
        ST_Distance(s.geog, ST_Point(a.geo_center_lon, a.geo_center_lat)::geography) ASC,
        a.area_key ASC
    LIMIT 1
)
WHERE s.district IS NOT NULL
  AND s.geog IS NOT NULL
  AND s.area_key IS NULL;  -- safely re-runnable: only assign unassigned rows, never re-derive

-- ── 3. Fail-loud guard (AC per #1830): distinguish "district did not normalise" (a defect,
--       made visible) from "no area within 10km" (legal, silent) ─────────────────────────────
--
-- For every school still left with area_key IS NULL after the backfill above (district and
-- geog both present — i.e. a candidate that COULD have matched), classify:
--   * If the school's normalised district matches AT LEAST ONE configured area's normalised
--     district, but none is within 10km -> LEGAL ("too far"), not reported.
--   * If NO configured area shares that normalised district bucket at all -> the district
--     string produced a bucket with zero possible matches. This is either a genuine
--     normalisation gap (a new/unhandled spelling, exactly this issue's defect class) or a
--     known, accepted data-coverage gap (e.g. 'bengaluru rural' today, per the header note
--     above) — either way it is now VISIBLE instead of silently vanishing into a NULL area_key.
--
-- RAISE WARNING (never EXCEPTION): a legitimate deploy with schools that are genuinely
-- >10km from any area, or with intentionally out-of-catalogue districts, must never be
-- blocked by this guard. It is a visibility aid, not a hard gate.
--
-- RE-RUNNABILITY: the detection query is a separate STABLE function
-- (check_unnormalised_school_districts), not inline in the DO block below, specifically so it
-- can be invoked again LATER by a seed/ops path (e.g. after the UDISE seed is eventually
-- loaded) via `SELECT public.check_unnormalised_school_districts();` — a one-shot DO block at
-- Flyway-apply time can only ever observe the ~40-row curated fixture present today, never
-- data loaded after migrations run. Wiring an actual post-seed caller is left to that future
-- seed/ops work; this migration only makes the check re-invocable.

CREATE OR REPLACE FUNCTION public.check_unnormalised_school_districts()
RETURNS TEXT
LANGUAGE sql
STABLE
AS $$
    SELECT string_agg(
        DISTINCT format('district=%L (normalises to %L): %s school(s)', district_raw, district_norm, cnt),
        E'\n' ORDER BY format('district=%L (normalises to %L): %s school(s)', district_raw, district_norm, cnt)
    )
    FROM (
        SELECT
            s.district AS district_raw,
            public.normalise_school_district(s.district) AS district_norm,
            COUNT(*) AS cnt
        FROM schools s
        WHERE s.area_key IS NULL
          AND s.district IS NOT NULL
          AND s.geog IS NOT NULL
        GROUP BY s.district, district_norm
        HAVING NOT EXISTS (
            SELECT 1
            FROM areas a
            WHERE public.normalise_school_district(a.district) = public.normalise_school_district(s.district)
        )
    ) AS buckets_with_zero_areas;
$$;

DO $$
DECLARE
    v_unmatched_districts TEXT := public.check_unnormalised_school_districts();
BEGIN
    IF v_unmatched_districts IS NOT NULL THEN
        RAISE WARNING E'V111 fail-loud guard: the following school district(s) have NO configured Discover area sharing their normalised district bucket (area_key stays NULL for ALL of them — not merely rows outside the 10km cap):\n%\nThis is either (a) a district-string spelling this CASE does not yet normalise (a defect — extend the CASE), or (b) a district with genuinely no area catalogue coverage yet (an accepted, documented gap, e.g. Bengaluru Rural — see V111 header). Review before assuming these schools are correctly excluded from Discover.', v_unmatched_districts;
    END IF;
END $$;
